#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package Abot@2.0.70 #:package Abotx@2.1.12 #:package Newtonsoft.Json@13.0.3 #:package System.Drawing.Common@9.0.8 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using Microsoft.Extensions.DependencyInjection; using Microsoft.Extensions.Logging; using System.Collections.Concurrent; using System.Drawing; using System.Diagnostics; using System.Reflection; using Abot2.Core; using Abot2.Crawler; using Abot2.Poco;  var config = new CrawlConfiguration {     MaxPagesToCrawl = 10, // 仅爬取 10 个页面     MinCrawlDelayPerDomainMilliSeconds = 3000 // 请求之间等待 3 秒 };   var crawler = new PoliteWebCrawler(config);   // 注册事件以处理已爬取的页面 crawler.PageCrawlCompleted += (sender, e) => {     var httpStatus = e.CrawledPage.HttpResponseMessage.StatusCode;     var crawledPage = e.CrawledPage;     Console.WriteLine($"已爬取：{crawledPage.Uri.AbsoluteUri}");          // 访问页面内容     if (crawledPage.Content.Text != null)     {         // 在此处理页面内容         Console.WriteLine(crawledPage.Content.Text);     } };   // 开始爬取 var crawlResult = await crawler.CrawlAsync(new Uri("https://github.com/amis92/csharp-source-generators"));
